import { graphql } from "./gql";

// monday.com GraphQL operations used by the ERP (API version pinned in monday.client.ts). Types are
// generated by `bun run monday:codegen`; change an operation, then run it again.

// who connected: identifies the account, so reconnecting to the same account keeps the board config
export const MeQuery = graphql(`
  query Me {
    me {
      id
      name
      account {
        id
        name
        slug
      }
    }
  }
`);

// boards to pick from in Integrações, most recently used first
export const BoardsQuery = graphql(`
  query Boards($limit: Int!, $page: Int!) {
    boards(limit: $limit, page: $page, state: active, order_by: used_at) {
      id
      name
      workspace {
        name
      }
      groups {
        id
        title
      }
      columns {
        id
        title
        type
      }
    }
  }
`);

export const BoardQuery = graphql(`
  query Board($id: ID!) {
    boards(ids: [$id]) {
      id
      name
      groups {
        id
        title
      }
      columns {
        id
        title
        type
      }
    }
  }
`);

// create_labels_if_missing: a categoria/ação value that isn't a status/dropdown label yet is added
export const CreateItemMutation = graphql(`
  mutation CreateItem($boardId: ID!, $groupId: String, $name: String!, $columnValues: JSON) {
    create_item(
      board_id: $boardId
      group_id: $groupId
      item_name: $name
      column_values: $columnValues
      create_labels_if_missing: true
    ) {
      id
      name
      url
    }
  }
`);

// the full description goes in an update (monday's comments) on the item
export const CreateUpdateMutation = graphql(`
  mutation CreateUpdate($itemId: ID!, $body: String!) {
    create_update(item_id: $itemId, body: $body) {
      id
    }
  }
`);
